INSERT INTO cmd_command_type VALUES('book_route_passengers','Book route passengers');
INSERT INTO cmd_domain_event_type VALUES('route_passengers_booked','Route passengers booked');
CREATE TABLE cmd_passenger_booking_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),journey_id bigint NOT NULL,ship_id bigint NOT NULL,revenue_availability_cycle_id bigint NOT NULL,passage_class text NOT NULL REFERENCES rule_passage_class(passage_class),passenger_count integer NOT NULL CHECK(passenger_count>0),total_fare_minor bigint NOT NULL CHECK(total_fare_minor>=0),FOREIGN KEY(journey_id,campaign_id) REFERENCES journey_journey(journey_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),FOREIGN KEY(revenue_availability_cycle_id,campaign_id) REFERENCES journey_revenue_availability_cycle(revenue_availability_cycle_id,campaign_id));
CREATE TABLE cmd_passenger_booking_line(command_id bigint NOT NULL REFERENCES cmd_passenger_booking_receipt(command_id),line_order smallint NOT NULL CHECK(line_order>0),campaign_id bigint NOT NULL,passenger_actor_id bigint NOT NULL,journey_passage_id bigint NOT NULL,PRIMARY KEY(command_id,line_order),FOREIGN KEY(passenger_actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(journey_passage_id,campaign_id) REFERENCES journey_passage(journey_passage_id,campaign_id));
